"""Risque et performance : drawdown, ratios, VaR et pertes extrêmes, types de risque."""
from __future__ import annotations

from patrick.knowledge.dictionary import d

T = "risque"
TERMS = [
    d(T, "drawdown", "Drawdown et perte maximale (max drawdown)", "Drawdown and maximum drawdown", 2,
      "Le drawdown est la baisse depuis le dernier sommet ; la perte maximale est le pire de ces creux sur la période. Contrairement à la volatilité, il décrit ce que vit un investisseur : un fonds à −35 % doit gagner +54 % pour revenir à zéro.",
      "Drawdown is the decline from the last peak; maximum drawdown is the worst such trough over the period. Unlike volatility, it describes what an investor experiences: a fund down 35% needs +54% to get back to zero.",
      formula=r"DD_t = \frac{V_t}{\max_{s \le t} V_s} - 1", see="duree_drawdown calmar_ratio", alias="MDD; perte maximale"),
    d(T, "duree_drawdown", "Durée d'un drawdown", "Drawdown duration", 2,
      "Temps nécessaire pour retrouver un sommet après une baisse. Une stratégie peut avoir un drawdown modéré mais rester sous l'eau plusieurs années : ce que peu d'investisseurs supportent.",
      "Time needed to recover a peak after a decline. A strategy may have a moderate drawdown yet stay underwater for years: something few investors tolerate.",
      see="drawdown ulcer_index"),
    d(T, "sharpe_ratio", "Ratio de Sharpe", "Sharpe ratio", 2,
      "Rendement excédentaire (au-dessus du taux sans risque) par unité de volatilité : la référence du rendement ajusté du risque. Un ratio annualisé de 0,4 à 0,5 est celui d'un marché actions ; au-dessus de 1, on soupçonne un gain trop beau, surtout sur un backtest court.",
      "Excess return (above the risk-free rate) per unit of volatility: the reference of risk-adjusted return. An annualised ratio of 0.4–0.5 is typical of an equity market; above 1, suspect a gain that is too good, especially on a short backtest.",
      formula=r"SR = \frac{E[R_p] - R_f}{\sigma_p}", see="sortino_ratio sharpe_probabiliste deflated_sharpe"),
    d(T, "sharpe_probabiliste", "Ratio de Sharpe probabiliste (PSR)", "Probabilistic Sharpe ratio (PSR)", 3,
      "Probabilité que le vrai Sharpe dépasse un seuil, compte tenu de la longueur de l'historique, de l'asymétrie et du kurtosis des rendements. Un Sharpe estimé sur trois ans de données est entouré d'une grande incertitude que le PSR chiffre.",
      "Probability that the true Sharpe exceeds a threshold, given the length of history and the skewness and kurtosis of returns. A Sharpe estimated on three years of data carries wide uncertainty that the PSR quantifies.",
      see="sharpe_ratio deflated_sharpe", alias="PSR"),
    d(T, "sortino_ratio", "Ratio de Sortino", "Sortino ratio", 2,
      "Comme le Sharpe, mais divise le rendement excédentaire par la seule volatilité des pertes (en dessous d'un seuil) : on ne pénalise pas la volatilité à la hausse.",
      "Like the Sharpe, but divides excess return by the volatility of losses alone (below a threshold): upside volatility is not penalised.",
      formula=r"\text{Sortino} = \frac{E[R_p] - R_f}{\sigma_{\text{baisse}}}", see="sharpe_ratio semi_variance"),
    d(T, "semi_variance", "Semi-variance et déviation à la baisse", "Semivariance and downside deviation", 3,
      "Variance calculée uniquement sur les rendements inférieurs à un seuil (zéro ou le taux sans risque) : elle mesure le risque qu'on ressent, c'est-à-dire les pertes.",
      "Variance computed only on returns below a threshold (zero or the risk-free rate): it measures the risk one feels, that is, losses.",
      see="sortino_ratio variance"),
    d(T, "calmar_ratio", "Ratio de Calmar", "Calmar ratio", 2,
      "Rendement annualisé divisé par la perte maximale (en valeur absolue) : combien de rendement par unité de pire épisode. Très utilisé en gestion alternative et pour les stratégies de suivi de tendance.",
      "Annualised return divided by the maximum drawdown (absolute value): how much return per unit of worst episode. Widely used in alternative management and for trend-following strategies.",
      formula=r"\text{Calmar} = \frac{R_{\text{ann}}}{|MDD|}", see="drawdown sharpe_ratio"),
    d(T, "treynor_ratio", "Ratio de Treynor", "Treynor ratio", 3,
      "Rendement excédentaire par unité de risque systématique (bêta) plutôt que de volatilité totale. Il convient quand le portefeuille évalué n'est qu'une partie d'un portefeuille déjà diversifié.",
      "Excess return per unit of systematic risk (beta) rather than total volatility. It fits when the evaluated portfolio is only a part of an already diversified portfolio.",
      formula=r"T = \frac{E[R_p] - R_f}{\beta_p}", see="beta sharpe_ratio"),
    d(T, "information_ratio", "Ratio d'information", "Information ratio", 3,
      "Rendement actif (au-dessus du benchmark) divisé par la tracking error : la qualité de la valeur ajoutée d'un gérant par unité de risque pris par rapport à l'indice. Un ratio de 0,5 est considéré bon sur la durée.",
      "Active return (above the benchmark) divided by tracking error: the quality of a manager's value-added per unit of risk taken relative to the index. A ratio of 0.5 is considered good over time.",
      formula=r"IR = \frac{E[R_p - R_b]}{\sigma(R_p - R_b)}", see="tracking_error alpha_jensen", alias="IR"),
    d(T, "tracking_error", "Tracking error", "Tracking error", 3,
      "Volatilité (annualisée) de l'écart de rendement entre un portefeuille et son benchmark. Une gestion indicielle vise une tracking error proche de zéro ; une gestion active en accepte 2 à 6 %.",
      "(Annualised) volatility of the return difference between a portfolio and its benchmark. Index management targets a tracking error near zero; active management accepts 2–6%.",
      see="information_ratio benchmark tracking_difference"),
    d(T, "alpha_jensen", "Alpha de Jensen", "Jensen's alpha", 3,
      "Rendement obtenu au-delà de ce que prévoit le CAPM compte tenu du bêta : α = R_p − [R_f + β (R_m − R_f)]. Un alpha positif et statistiquement significatif est la preuve recherchée d'un talent ; en pratique il est rare et fragile.",
      "Return obtained beyond what CAPM predicts given beta: α = R_p − [R_f + β (R_m − R_f)]. A positive, statistically significant alpha is the sought proof of skill; in practice it is rare and fragile.",
      formula=r"\alpha = R_p - \left[R_f + \beta\,(R_m - R_f)\right]", see="capm beta target_alpha", alias="alpha"),
    d(T, "capture_ratios", "Ratios de capture haussière et baissière", "Up and down capture ratios", 3,
      "Part de la hausse (resp. de la baisse) du benchmark que capte un portefeuille les mois où le benchmark monte (resp. baisse). Une capture de 80 % à la baisse et 95 % à la hausse est le profil recherché.",
      "Share of the benchmark's rise (resp. fall) that a portfolio captures in months when the benchmark rises (resp. falls). 80% downside and 95% upside capture is the sought profile.",
      see="benchmark beta"),
    d(T, "skewness", "Asymétrie (skewness)", "Skewness", 2,
      "Troisième moment standardisé d'une distribution. Négative : les grosses pertes sont plus fréquentes que les gros gains (cas de nombreuses stratégies qui « ramassent des pièces devant un rouleau compresseur »). Positive : l'inverse.",
      "Third standardised moment of a distribution. Negative: big losses are more frequent than big gains (the case of many strategies that 'pick up coins in front of a steamroller'). Positive: the reverse.",
      formula=r"S = E\left[\left(\frac{X-\mu}{\sigma}\right)^3\right]", see="kurtosis queues_epaisses"),
    d(T, "kurtosis", "Aplatissement (kurtosis)", "Kurtosis", 2,
      "Quatrième moment standardisé : mesure l'épaisseur des queues. Une loi normale a un kurtosis de 3 ; les rendements financiers journaliers en ont souvent 6 à 20, donc beaucoup plus de valeurs extrêmes que ne le prévoit la loi normale.",
      "Fourth standardised moment: measures tail thickness. A normal distribution has kurtosis 3; daily financial returns often have 6 to 20, hence far more extreme values than the normal predicts.",
      formula=r"K = E\left[\left(\frac{X-\mu}{\sigma}\right)^4\right]", see="skewness queues_epaisses"),
    d(T, "queues_epaisses", "Queues épaisses", "Fat tails", 2,
      "Les grands mouvements arrivent plus souvent que sous une loi normale : un recul de 5 écarts-types, quasi impossible en théorie gaussienne, se produit plusieurs fois par décennie. D'où l'usage de lois de Student ou de méthodes de théorie des valeurs extrêmes.",
      "Large moves occur more often than under a normal law: a 5-standard-deviation fall, nearly impossible in Gaussian theory, happens several times a decade. Hence the use of Student laws or extreme-value methods.",
      see="kurtosis var_methodes", alias="fat tails; leptokurtique"),
    d(T, "var_methodes", "VaR : méthodes de calcul", "VaR: calculation methods", 3,
      "La VaR peut se calculer par la loi normale (paramétrique), par les rendements passés (historique) ou par simulation (Monte-Carlo). La première sous-estime les queues, la deuxième dépend de l'historique, la troisième du modèle supposé.",
      "VaR can be computed with the normal law (parametric), from past returns (historical) or by simulation (Monte Carlo). The first understates tails, the second depends on history, the third on the assumed model.",
      see="exp_var_es backtest_var"),
    d(T, "backtest_var", "Backtest d'une VaR", "VaR backtest", 3,
      "Compter combien de fois la perte réelle a dépassé la VaR prévue et vérifier que ce taux vaut le niveau annoncé (1 % pour une VaR à 99 %), avec des dépassements non groupés : tests de Kupiec et de Christoffersen.",
      "Counting how often the actual loss exceeded the forecast VaR and checking that the rate equals the stated level (1% for a 99% VaR), with non-clustered exceedances: Kupiec and Christoffersen tests.",
      course="econometrie#7-6-backtest-de-la-var", see="var_methodes kupiec_christoffersen"),
    d(T, "stress_test", "Test de résistance (stress test)", "Stress test", 2,
      "Évaluation de la perte d'un portefeuille dans un scénario extrême choisi à l'avance (krach de 2008, choc de taux de +2 points, 2020). Il complète la VaR, qui ne dit rien de la taille des pertes au-delà de son seuil.",
      "Assessment of a portfolio's loss in an extreme scenario chosen in advance (2008 crash, +2-point rate shock, 2020). It complements VaR, which says nothing about the size of losses beyond its threshold.",
      see="analyse_scenarios exp_var_es"),
    d(T, "analyse_scenarios", "Analyse de scénarios", "Scenario analysis", 2,
      "Évaluer le portefeuille sous plusieurs futurs plausibles (récession, inflation persistante, choc géopolitique) avec des hypothèses explicites sur chaque actif. Moins mécanique que la VaR, elle fait réfléchir aux dépendances.",
      "Evaluating the portfolio under several plausible futures (recession, persistent inflation, geopolitical shock) with explicit assumptions on each asset. Less mechanical than VaR, it forces thinking about dependencies.",
      see="stress_test"),
    d(T, "risque_systematique", "Risque systématique et spécifique", "Systematic and idiosyncratic risk", 2,
      "Le risque systématique (de marché) touche tous les actifs et ne se diversifie pas ; le spécifique (d'une entreprise) disparaît quand on détient assez de titres. La prime de risque rémunère le premier, pas le second.",
      "Systematic (market) risk affects all assets and cannot be diversified away; idiosyncratic (company) risk disappears when enough securities are held. The risk premium pays for the former, not the latter.",
      see="diversification beta"),
    d(T, "risque_liquidite", "Risque de liquidité", "Liquidity risk", 2,
      "Risque de ne pas pouvoir vendre (ou acheter) rapidement sans concession de prix importante, notamment en période de stress. Il se manifeste par un élargissement des fourchettes et une baisse de profondeur.",
      "Risk of being unable to sell (or buy) quickly without a major price concession, notably under stress. It shows as wider spreads and lower depth.",
      see="liquidite illiquidite_amihud"),
    d(T, "risque_contrepartie", "Risque de contrepartie", "Counterparty risk", 2,
      "Risque que l'autre partie d'un contrat ne tienne pas ses engagements : la banque d'un swap, l'émetteur d'un ETN, le courtier. Les chambres de compensation et les garanties (collatéral) le réduisent.",
      "Risk that the other party to a contract fails its obligations: the bank in a swap, the ETN issuer, the broker. Clearing houses and collateral reduce it.",
      see="chambre_de_compensation etn"),
    d(T, "risque_modele", "Risque de modèle", "Model risk", 3,
      "Risque de perte dû à un modèle faux, mal calibré, mal utilisé ou employé hors de son domaine de validité. La pire version est la confiance excessive dans un backtest sur-ajusté.",
      "Risk of loss from a wrong, miscalibrated, misused or out-of-scope model. The worst version is excessive confidence in an over-fitted backtest.",
      see="surapprentissage backtest_notion"),
    d(T, "risque_concentration", "Risque de concentration", "Concentration risk", 2,
      "Risque d'avoir une trop grande part du portefeuille dans un actif, un secteur, un pays ou un facteur. Le portefeuille semble diversifié en nombre de lignes mais ne l'est pas en sources de risque.",
      "Risk of having too much of the portfolio in one asset, sector, country or factor. The portfolio looks diversified by number of holdings but is not by sources of risk.",
      see="diversification risk_parity"),
    d(T, "gap_risk", "Risque de gap", "Gap risk", 2,
      "Risque qu'un cours saute d'un niveau à un autre sans passer par les prix intermédiaires (nuit, annonce) : un ordre stop ne protège alors pas au prix voulu. Il est la raison pour laquelle les pertes réelles excèdent souvent les pertes prévues.",
      "Risk that a price jumps from one level to another without trading in between (overnight, announcement): a stop order then does not protect at the intended price. It is why actual losses often exceed expected ones.",
      see="stop_loss gap_overnight"),
    d(T, "correlation_de_crise", "Corrélation en période de crise", "Correlation in a crisis", 3,
      "En période de stress, les corrélations entre actifs risqués montent vers 1 : la diversification fonctionne le moins quand on en a le plus besoin. Une matrice de corrélation estimée en temps calme sous-estime le risque de crise.",
      "Under stress, correlations among risky assets rise toward 1: diversification works least when it is needed most. A correlation matrix estimated in calm times underestimates crisis risk.",
      see="diversification krach tail_dependence_intro"),
    d(T, "risque_taux", "Risque de taux", "Interest-rate risk", 2,
      "Sensibilité de la valeur d'un actif ou d'un passif aux variations des taux. Il est mesuré par la duration et le DV01 pour les obligations, et touche aussi les actions (taux d'actualisation), l'immobilier et les banques.",
      "Sensitivity of an asset's or liability's value to changes in rates. It is measured by duration and DV01 for bonds, and also affects stocks (discount rate), real estate and banks.",
      see="duration dv01"),
    d(T, "risque_change", "Risque de change", "Currency risk", 1,
      "Risque que les variations d'une devise modifient la valeur d'un actif détenu en monnaie étrangère. Un investisseur européen sur le S&P 500 gagne ou perd aussi selon l'EUR/USD ; on peut se couvrir, à un coût lié aux taux.",
      "Risk that changes in a currency alter the value of an asset held in a foreign currency. A European investor in the S&P 500 also gains or loses with EUR/USD; one can hedge, at a cost tied to interest rates.",
      see="devise_change taux_de_change_couvert"),
    d(T, "ulcer_index", "Indice d'ulcère (ulcer index)", "Ulcer index", 3,
      "Racine de la moyenne des carrés des drawdowns : il tient compte à la fois de la profondeur et de la durée des baisses, contrairement à la perte maximale seule. Le ratio « martin » divise le rendement excédentaire par lui.",
      "Root of the mean of squared drawdowns: it accounts for both the depth and duration of declines, unlike the maximum drawdown alone. The 'Martin ratio' divides excess return by it.",
      see="drawdown duree_drawdown"),
    d(T, "omega_ratio", "Ratio Omega", "Omega ratio", 3,
      "Rapport entre les gains au-dessus d'un seuil et les pertes en dessous, sur toute la distribution des rendements : il utilise toute la forme de la loi, pas seulement moyenne et variance.",
      "Ratio of gains above a threshold to losses below it, across the whole return distribution: it uses the full shape of the law, not just mean and variance.",
      see="sharpe_ratio sortino_ratio"),
    d(T, "gain_to_pain", "Ratio gain/douleur (gain-to-pain)", "Gain-to-pain ratio", 3,
      "Somme des rendements divisée par la somme des pertes en valeur absolue. Simple et sans hypothèse de loi, il est apprécié pour les stratégies à profil asymétrique.",
      "Sum of returns divided by the sum of absolute losses. Simple and distribution-free, it is liked for strategies with asymmetric profiles.",
      see="omega_ratio"),
    d(T, "sharpe_ajuste_autocorrelation", "Sharpe corrigé de l'autocorrélation", "Autocorrelation-adjusted Sharpe", 3,
      "Annualiser un Sharpe mensuel par √12 suppose des rendements indépendants. Avec de l'autocorrélation positive (actifs peu liquides, valorisations lissées), le vrai Sharpe annuel est plus faible : Lo (2002) donne le facteur de correction.",
      "Annualising a monthly Sharpe by √12 assumes independent returns. With positive autocorrelation (illiquid assets, smoothed valuations), the true annual Sharpe is lower: Lo (2002) gives the correction factor.",
      see="sharpe_ratio autocorrelation_notion"),
    d(T, "budget_de_risque", "Budget de risque", "Risk budget", 3,
      "Répartition du risque total d'un portefeuille entre ses lignes ou stratégies, fixée à l'avance (par exemple 10 % de la variance par ligne). On pilote la contribution au risque plutôt que le poids en capital.",
      "Allocation of a portfolio's total risk among its holdings or strategies, set in advance (for example 10% of variance per holding). One manages risk contribution rather than capital weight.",
      see="risk_parity contribution_au_risque"),
    d(T, "contribution_au_risque", "Contribution au risque", "Risk contribution", 3,
      "Part de la volatilité du portefeuille attribuable à chaque ligne : poids × covariance de la ligne avec le portefeuille / variance du portefeuille. Elle diffère souvent beaucoup du poids : 10 % du capital peut valoir 30 % du risque.",
      "Share of portfolio volatility attributable to each holding: weight × covariance of the holding with the portfolio / portfolio variance. It often differs greatly from weight: 10% of capital can be 30% of risk.",
      formula=r"RC_i = w_i\,\frac{(\Sigma w)_i}{w^\top \Sigma w}", see="budget_de_risque covariance"),
    d(T, "volatilite_cible", "Ciblage de volatilité", "Volatility targeting", 3,
      "Ajuster l'exposition pour garder une volatilité constante (par exemple 10 %) : moins investi quand le marché est agité, plus quand il est calme. Il lisse le risque et améliore souvent le Sharpe car la volatilité est prévisible.",
      "Adjusting exposure to hold constant volatility (for example 10%): less invested when markets are turbulent, more when calm. It smooths risk and often improves the Sharpe because volatility is forecastable.",
      formula=r"w_t = \frac{\sigma_{\text{cible}}}{\hat\sigma_t}", see="garch_notion kelly"),
    d(T, "tail_dependence_intro", "Dépendance extrême (aperçu)", "Tail dependence (overview)", 3,
      "Tendance de deux actifs à chuter ensemble dans les cas extrêmes, au-delà de ce que dit leur corrélation moyenne. Les copules mesurent cette dépendance de queue, que la corrélation de Pearson ignore.",
      "Tendency of two assets to fall together in extreme cases, beyond what their average correlation says. Copulas measure this tail dependence, which Pearson correlation ignores.",
      see="exp_tail copule"),
    d(T, "perte_attendue_inattendue", "Perte attendue et perte inattendue", "Expected and unexpected loss", 3,
      "La perte attendue est la moyenne des pertes probables (provisionnée comme un coût) ; la perte inattendue est l'écart autour de cette moyenne, que les fonds propres doivent absorber. Vocabulaire du risque de crédit.",
      "Expected loss is the average of probable losses (provisioned as a cost); unexpected loss is the deviation around that mean, which capital must absorb. Credit-risk vocabulary.",
      see="defaut_recouvrement"),
]
